func getModifiedArray(length int, updates [][]int) []int {
  res:= make([]int, length);

  var wg sync.WaitGroup
  wg.Add(len(updates))
  for idx:=range updates{
      go func(index int){
          defer wg.Done()
          s:= updates[index][0]
          e:=updates[index][1];
          c:= updates[index][2];

          for i:=s;i<=e; i++{
              res[i]+=c;
          }
      }(idx)
  }

  wg.Wait();

  return res
}
